      "description": "First-differencing retains comparable |r| for BOTH channel types",
      "diversity_retention": 0.9523,
      "perplexity_retention": 1.0023,
      "implication": "Differencing is NOT a blanket power-loss mechanism. Both channel types preserve ~95%+ of correlation magnitude."
    },
    "finding_2_granger_asymmetry": {
      "description": "Granger F-stat is order-of-magnitude lower for perplexity despite comparable |r|",
      "diversity_F_median": 67.83,
      "perplexity_F_median": 11.48,
      "F_ratio": 5.9,
      "within_experiment_F_ratio": "20-28x (a060, reactive_d1)",
      "implication": "The low Granger F for perplexity is NOT caused by differencing removing signal. The raw |r| is equally high (~0.90). The low F reflects absence of LAGGED predictive structure."
    },
    "finding_3_temporal_structure": {
      "description": "Perplexity correlations are contemporaneous (lag≈0), diversity correlations are lagged (canary leads)",
      "diversity_lag_negative_rate": "81% (canary leads downstream)",
      "perplexity_lag_zero_rate": "50% (contemporaneous)",
      "implication": "Canary→perplexity is contemporaneous co-movement, not lagged causation. Canary→diversity shows genuine temporal precedence."
    },
    "reviewer_response": "First-differencing retains 95% of |r| for diversity channels (n=243) and 100% for perplexity channels (n=8). This parity rules out blanket power loss. The asymmetry in Granger F-statistics (diversity median F=67.8 vs perplexity median F=11.5; within-experiment ratio 20-28x) instead reflects a structural difference: perplexity correlations peak at lag≈0 (contemporaneous, 50% of cases), while diversity correlations peak at lag<0 (canary temporally leads, 81% of cases). Granger causality tests lagged predictive power, so contemporaneous co-movement naturally produces lower F-statistics regardless of differencing."
  }
